import{_ as i,a0 as p,w as l,s as d,I as n,x as a,a1 as e,A as o,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const q=JSON.parse('{"title":"使用 VS Code 进行 Python 编程 | LCTT x X-CMD","titleTemplate":false,"description":"使用 VS Code 进行 Python 编程 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 VS Code 进行 Python 编程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 VS Code 进行 Python 编程 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180730 How to use VS Code for your Python projects","title":"使用 VS Code 进行 Python 编程","tag":"201809","desc":""},"relativePath":"201809/20180730 How to use VS Code for your Python projects.md","filePath":"[post].md"}'),h={name:"201809/20180730 How to use VS Code for your Python projects.md"};function u(g,s,c,k,f,b){const t=p("Link");return l(),d("div",null,[s[18]||(s[18]=n("h1",{id:"使用-vs-code-进行-python-编程",tabindex:"-1"},[a("使用 VS Code 进行 Python 编程 "),n("a",{class:"header-anchor",href:"#使用-vs-code-进行-python-编程","aria-label":"Permalink to “使用 VS Code 进行 Python 编程”"},"​")],-1)),s[19]||(s[19]=n("p",null,[n("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/07/pythonvscode-816x345.jpg",alt:""})],-1)),s[20]||(s[20]=n("p",null,"Visual Studio Code，简称 VS Code，是一个开源的文本编辑器，包含用于构建和调试应用程序的工具。安装启用 Python 扩展后，VS Code 可以配置成理想的 Python 开发工作环境。本文将介绍一些有用的 VS Code 扩展，并配置它们以充分提高 Python 开发效率。",-1)),n("p",null,[s[1]||(s[1]=a("如果你的计算机上还没有安装 VS Code，可以参考文章 ",-1)),e(t,{href:"https://fedoramagazine.org/using-visual-studio-code-fedora/"},{default:o(()=>[...s[0]||(s[0]=[a("在 Fedora 上使用 VS Code",-1)])]),_:1}),s[2]||(s[2]=a(" 来安装。",-1))]),s[21]||(s[21]=r(`<h3 id="在-vs-code-中安装-python-扩展" tabindex="-1">在 VS Code 中安装 Python 扩展 <a class="header-anchor" href="#在-vs-code-中安装-python-扩展" aria-label="Permalink to “在 VS Code 中安装 Python 扩展”">​</a></h3><p>首先，为了更方便地在 VS Code 中进行 Python 开发，需要从 VS Code 扩展商店中安装 Python 扩展。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/07/Peek-2018-07-27-09-44.gif" alt=""></p><p>Python 扩展安装完成后，就可以开始配置 Python 扩展了。</p><p>VS Code 通过两个 JSON 文件管理设置:</p><ul><li>一个文件用于 VS Code 的全局设置，作用于所有的项目</li><li>另一个文件用于特殊设置，作用于单独项目</li></ul><p>可以用快捷键 <code>Ctrl+,</code> （逗号）打开全局设置，也可以通过 <strong>文件 -&gt; 首选项 -&gt; 设置</strong> 来打开。</p><h4 id="设置-python-路径" tabindex="-1">设置 Python 路径 <a class="header-anchor" href="#设置-python-路径" aria-label="Permalink to “设置 Python 路径”">​</a></h4><p>您可以在全局设置中配置 <code>python.pythonPath</code> 使 VS Code 自动为每个项目选择最适合的 Python 解释器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// 将设置放在此处以覆盖默认设置和用户设置。</span></span>
<span class="line"><span>// Path to Python, you can use a custom version of Python by modifying this setting to include the full path.</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;python.pythonPath&quot;:&quot;\${workspaceRoot}/.venv/bin/python&quot;,</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这样，VS Code 将使用虚拟环境目录 <code>.venv</code> 下项目根目录中的 Python 解释器。</p><h4 id="使用环境变量" tabindex="-1">使用环境变量 <a class="header-anchor" href="#使用环境变量" aria-label="Permalink to “使用环境变量”">​</a></h4><p>默认情况下，VS Code 使用项目根目录下的 <code>.env</code> 文件中定义的环境变量。 这对于设置环境变量很有用，如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PYTHONWARNINGS=&quot;once&quot;</span></span></code></pre></div><p>可使程序在运行时显示警告。</p><p>可以通过设置 <code>python.envFile</code> 来加载其他的默认环境变量文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Absolute path to a file containing environment variable definitions.</span></span>
<span class="line"><span>&quot;python.envFile&quot;: &quot;\${workspaceFolder}/.env&quot;,</span></span></code></pre></div><h3 id="代码分析" tabindex="-1">代码分析 <a class="header-anchor" href="#代码分析" aria-label="Permalink to “代码分析”">​</a></h3><p>Python 扩展还支持不同的代码分析工具（pep8、flake8、pylint）。要启用你喜欢的或者正在进行的项目所使用的分析工具，只需要进行一些简单的配置。</p><p>扩展默认情况下使用 pylint 进行代码分析。你可以这样配置以使用 flake8 进行分析：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;python.linting.pylintEnabled&quot;: false,</span></span>
<span class="line"><span>&quot;python.linting.flake8Path&quot;: &quot;\${workspaceRoot}/.venv/bin/flake8&quot;,</span></span>
<span class="line"><span>&quot;python.linting.flake8Enabled&quot;: true,</span></span>
<span class="line"><span>&quot;python.linting.flake8Args&quot;: [&quot;--max-line-length=90&quot;],</span></span></code></pre></div><p>启用代码分析后，分析器会在不符合要求的位置加上波浪线，鼠标置于该位置，将弹窗提示其原因。注意，项目的虚拟环境中需要安装有 flake8，此示例方能有效。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/07/Peek-2018-07-27-12-05.gif" alt=""></p><h3 id="格式化代码" tabindex="-1">格式化代码 <a class="header-anchor" href="#格式化代码" aria-label="Permalink to “格式化代码”">​</a></h3><p>可以配置 VS Code 使其自动格式化代码。目前支持 autopep8、black 和 yapf。下面的设置将启用 “black” 模式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Provider for formatting. Possible options include &#39;autopep8&#39;, &#39;black&#39;, and &#39;yapf&#39;.</span></span>
<span class="line"><span>&quot;python.formatting.provider&quot;: &quot;black&quot;,</span></span>
<span class="line"><span>&quot;python.formatting.blackPath&quot;: &quot;\${workspaceRoot}/.venv/bin/black&quot;</span></span>
<span class="line"><span>&quot;python.formatting.blackArgs&quot;: [&quot;--line-length=90&quot;],</span></span>
<span class="line"><span>&quot;editor.formatOnSave&quot;: true,</span></span></code></pre></div><p>如果不需要编辑器在保存时自动格式化代码，可以将 <code>editor.formatOnSave</code> 设置为 <code>false</code> 并手动使用快捷键 <code>Ctrl + Shift + I</code> 格式化当前文档中的代码。 注意，项目的虚拟环境中需要安装有 black，此示例方能有效。</p><h3 id="运行任务" tabindex="-1">运行任务 <a class="header-anchor" href="#运行任务" aria-label="Permalink to “运行任务”">​</a></h3><p>VS Code 的一个重要特点是它可以运行任务。需要运行的任务保存在项目根目录中的 JSON 文件中。</p><h4 id="运行-flask-开发服务" tabindex="-1">运行 flask 开发服务 <a class="header-anchor" href="#运行-flask-开发服务" aria-label="Permalink to “运行 flask 开发服务”">​</a></h4><p>这个例子将创建一个任务来运行 Flask 开发服务器。 使用一个可以运行外部命令的基本模板来创建新的工程：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/07/Peek-2018-07-27-13-26.gif" alt=""></p><p>编辑如下所示的 <code>tasks.json</code> 文件，创建新任务来运行 Flask 开发服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>  // See https://go.microsoft.com/fwlink/?LinkId=733558</span></span>
<span class="line"><span>  // for the documentation about the tasks.json format</span></span>
<span class="line"><span>  &quot;version&quot;: &quot;2.0.0&quot;,</span></span>
<span class="line"><span>  &quot;tasks&quot;: [</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      &quot;label&quot;: &quot;Run Debug Server&quot;,</span></span>
<span class="line"><span>      &quot;type&quot;: &quot;shell&quot;,</span></span>
<span class="line"><span>      &quot;command&quot;: &quot;\${workspaceRoot}/.venv/bin/flask run -h 0.0.0.0 -p 5000&quot;,</span></span>
<span class="line"><span>      &quot;group&quot;: {</span></span>
<span class="line"><span>          &quot;kind&quot;: &quot;build&quot;,</span></span>
<span class="line"><span>          &quot;isDefault&quot;: true</span></span>
<span class="line"><span>       }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Flask 开发服务使用环境变量来获取应用程序的入口点。 如 <strong>使用环境变量</strong> 一节所说，可以在 <code>.env</code> 文件中声明这些变量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>FLASK_APP=wsgi.py</span></span>
<span class="line"><span>FLASK_DEBUG=True</span></span></code></pre></div><p>这样就可以使用快捷键 <code>Ctrl + Shift + B</code> 来执行任务了。</p><h3 id="单元测试" tabindex="-1">单元测试 <a class="header-anchor" href="#单元测试" aria-label="Permalink to “单元测试”">​</a></h3><p>VS Code 还支持单元测试框架 pytest、unittest 和 nosetest。启用测试框架后，可以在 VS Code 中单独运行搜索到的单元测试，通过测试套件运行测试或者运行所有的测试。</p><p>例如，可以这样启用 pytest 测试框架：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;python.unitTest.pyTestEnabled&quot;: true,</span></span>
<span class="line"><span>&quot;python.unitTest.pyTestPath&quot;: &quot;\${workspaceRoot}/.venv/bin/pytest&quot;,</span></span></code></pre></div><p>注意，项目的虚拟环境中需要安装有 pytest，此示例方能有效。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/07/Peek-2018-07-27-15-33.gif" alt=""></p><hr>`,44)),n("p",null,[s[4]||(s[4]=a("via: ",-1)),e(t,{href:"https://fedoramagazine.org/vscode-python-howto/"},{default:o(()=>[...s[3]||(s[3]=[a("https://fedoramagazine.org/vscode-python-howto/",-1)])]),_:1})]),n("p",null,[s[9]||(s[9]=a("作者：",-1)),e(t,{href:"https://fedoramagazine.org"},{default:o(()=>[...s[5]||(s[5]=[a("Clément Verna",-1)])]),_:1}),s[10]||(s[10]=a(" 选题：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:o(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),e(t,{href:"https://github.com/idea2act"},{default:o(()=>[...s[7]||(s[7]=[a("idea2act",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:o(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:o(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const C=i(h,[["render",u]]);export{q as __pageData,C as default};
